from taf.internal.robot_typecasts import time_to_seconds, to_boolean



class IPConnectivityInterface(object):


    def test_ip_connectivity(self, remote_address, dscp, payload_size, source_address, timeout=120):
        """ TestIPConnectivity

        :param string remote_address: remoteAddress
        :param integer dscp: dscp
        :param integer payload_size: payloadSize
        :param string source_address: sourceAddress
        :param float timeout: Time to wait for positive procedure result.
        
        """
        timeout = time_to_seconds(timeout)
        str(remote_address)
        dscp = int(dscp)
        payload_size = int(payload_size)
        str(source_address)
        return self._api_client.execute_procedure(
            "testIpConnectivity", {"remoteAddress": remote_address, "dscp": dscp, "payloadSize": payload_size}, timeout)

    def start_ip_capture_file(self, measurement_point, uplane_capturing, password, timeout=120):
        """ StartIPCaptureFile

        :param string measurement_point: "NE_Terminated" or "Transport_Interface"
        :param boolean uplane_capturing: uplaneCapturing
        :param string password: password
        :param float timeout: Time to wait for positive procedure result.
        
        """
        timeout = time_to_seconds(timeout)
        assert measurement_point in ("NE_Terminated", "Transport_Interface")
        uplane_capturing = to_boolean(uplane_capturing)
        str(password)
        self._api_client.execute_procedure("startIPCaptureFile",
                                                {"measurementPoint": measurement_point, "uplaneCapturing": uplane_capturing, "password": password},
                                                timeout)

    def start_ip_capture_streaming(self, measurement_point, uplane_capturing, dst_mac_addr, egress_port_dn, timeout=120):
        """ StartIPCaptureStreaming

        :param string measurement_point: "NE_Terminated" or "Transport_Interface"
        :param boolean uplane_capturing: uplaneCapturing
        :param string dst_mac_addr: dstMacAddr
        :param string egress_port_dn: egressPortDN
        :param float timeout: Time to wait for positive procedure result.
        
        """
        timeout = time_to_seconds(timeout)
        assert measurement_point in ("NE_Terminated", "Transport_Interface")
        uplane_capturing = to_boolean(uplane_capturing)
        str(dst_mac_addr)
        str(egress_port_dn)
        self._api_client.execute_procedure("startIPCaptureStreaming",
                                                {"measurementPoint": measurement_point, "uplaneCapturing": uplane_capturing,
                                                 "dstMacAddr": dst_mac_addr, "egressPortDN": egress_port_dn}, timeout)

    def stop_ip_capture_file(self, timeout=120):
        """ StopIPCaptureFile

        :param float timeout: Time to wait for positive procedure result.
        
        """
        timeout = time_to_seconds(timeout)
        self._api_client.execute_procedure("stopIPCaptureFile", {}, timeout)

    def stop_ip_capture_streaming(self, timeout=120):
        """ StopIPCaptureStreaming

        :param float timeout: Time to wait for positive procedure result.
        
        """
        timeout = time_to_seconds(timeout)
        self._api_client.execute_procedure("stopIPCaptureStreaming", {}, timeout)

    def generate_ip_capture_file(self, timeout=120):
        """ GenerateIPCaptureFile

        :param float timeout: Time to wait for positive procedure result.
        
        """
        timeout = time_to_seconds(timeout)
        self._api_client.execute_procedure("generateIPCaptureFile", {}, timeout)

    def cancel_file_generating(self, timeout=120):
        """ cancelFileGenerating

        :param float timeout: Time to wait for positive procedure result.
        
        """
        timeout = time_to_seconds(timeout)
        self._api_client.execute_procedure("cancelFileGenerating", {}, timeout)

    def download_ip_capture_file(self, target_file_name, timeout=120):
        """ downloadIPCaptureFile

        :param string target_file_name: target filename.
        :param float timeout: Time to wait for positive procedure result.
        
        """
        timeout = time_to_seconds(timeout)
        return self._api_client.execute_infomodel_request("downloadIPCaptureFile", {}, timeout,
                                                               output_file_name=target_file_name)
